set -euo pipefail
upload_dir=$(getent passwd "$SUDO_USER" | cut -d: -f6)
cd /opt/news-flow/current
runuser -u news-flow -- /opt/news-flow/node/bin/node --input-type=module - <<'NODE'
import fs from 'node:fs';import {gzipSync} from 'node:zlib';import {createHash} from 'node:crypto';import {createRequire} from 'node:module';import {DatabaseSync} from 'node:sqlite';import {loadNewsRegistry} from './src/newsFlow/registry.mjs';import {NewsProxyPool,NewsHttpDriver} from './src/newsFlow/transport.mjs';import {NewsNetworkPool} from './src/newsFlow/networkPool.mjs';const require=createRequire('/opt/news-flow/current/package.json'),ch=require('cheerio'),root='/var/lib/news-flow/qc-recover25-20261122',registry=await loadNewsRegistry(),db=new DatabaseSync('/var/lib/news-flow/news-flow-runtime/write.sqlite',{readOnly:true}),rows=db.prepare("SELECT url,error FROM article_links WHERE site='edition.cnn.com' AND parse_status='fail'").all();db.close();const network=new NewsNetworkPool({workers:1}),pool=await NewsProxyPool.load('/etc/news-flow/proxies.json',{rotation:'request'}),driver=new NewsHttpDriver({state:{cacheResponses:false,failedUrl:()=>false,request:()=>null,reserve:()=>true,cache:()=>null,completeHttpResponse:()=>{}},network,pool,allowedDomains:registry.allowedDomains,siteCooldown:false,maxWireRequests:10}),r={at:new Date().toISOString(),rows:[]},clean=s=>String(s||'').normalize('NFC').replace(/[“”]/g,'"').replace(/[‘’]/g,"'").replace(/\s+/g,' ').trim();try{for(const row of rows){const url='https://lite.cnn.com'+new URL(row.url).pathname,p=await driver.get('qc-recover25-last-review',url,registry.sources.get('edition.cnn.com').config,[],{reviewFailed:true,taskRole:'article'}),o={...row,transportUrl:url,statusCode:p.statusCode,error:p.error||row.error};if(!p.error&&p.html){o.file=root+'/evidence/'+createHash('sha256').update(p.html).digest('hex')+'.gz';fs.writeFileSync(o.file,gzipSync(p.html));const $=ch.load(p.html),schemas=[];for(const e of $('script[type="application/ld+json"]').toArray())try{const a=JSON.parse($(e).text());schemas.push(...(Array.isArray(a)?a:[a]));}catch{}const a=schemas.find(a=>a['@type']==='NewsArticle');o.canonical=$('link[rel="canonical"]').attr('href');o.nativeHeadline=$('h2.headline').text();o.schemaHeadline=a?.headline;o.datePublished=a?.datePublished;o.nativeIsAccessibleForFree=a?.isAccessibleForFree;o.hasPart=a?.hasPart;o.descriptionChars=clean(a?.description).length;const body=$('article.article--lite').clone();body.find('.source--lite').remove();body.find('p').filter((i,e)=>clean($(e).text())==='See Full Web Article').remove();const schema=clean(a?.articleBody),paras=body.find('p.paragraph--lite').toArray().map(e=>clean($(e).text())).filter(Boolean);o.bodyExact=clean(body.text())===schema;o.schemaChars=schema.length;o.paragraphs=paras.length;let matched=0,cursor=0;const missing=[];for(const text of paras){const pos=schema.indexOf(text,cursor);if(pos<0)missing.push(text.slice(0,160));else{matched+=text.length;cursor=pos+text.length;}}o.schemaCoverage=matched/Math.max(1,schema.length);o.missingParagraphs=missing;}r.rows.push(o);}fs.writeFileSync(root+'/cnn-final-failures.json',JSON.stringify(r,null,2));console.log(JSON.stringify(r));}finally{await network.close();}
NODE
install -o "$SUDO_USER" -m 0600 /var/lib/news-flow/qc-recover25-20261122/cnn-final-failures.json "$upload_dir/.qc-recover25-cnn-final-failures.json"
